from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from typing import Any


def _text(value: Any) -> str:
    return "" if value is None else str(value)


def _fixed(value: Any, width: int) -> str:
    return _text(value)[:width].ljust(width)


def _ann_rev_cents(value: Any) -> str:
    text = _text(value)
    if not text.strip():
        amount = Decimal(0)
    else:
        try:
            amount = Decimal(text)
        except (InvalidOperation, ValueError) as exc:
            raise ValueError("ANN_REV must be a decimal number") from exc

    if not amount.is_finite():
        raise ValueError("ANN_REV must be finite")

    digits = len(amount.as_tuple().digits)
    exponent = amount.as_tuple().exponent
    precision = max(50, digits + abs(exponent) + 10)

    with localcontext() as context:
        context.prec = precision
        cents = (amount * Decimal(100)).quantize(
            Decimal(1), rounding=ROUND_HALF_UP
        )

    rendered = str(int(cents)).zfill(15)
    if len(rendered) != 15:
        raise ValueError("ANN_REV cents do not fit in the 15-character field")
    return rendered


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT record without a terminator."""
    account_id = _fixed(row.get("ACCT_ID", ""), 10)
    account_name = _fixed(row.get("ACCT_NM", ""), 40)
    region_code = _fixed(row.get("REGION_CD", ""), 3)
    annual_revenue = _ann_rev_cents(row.get("ANN_REV", ""))

    credit_hold = _text(row.get("CRED_HOLD", ""))
    if not credit_hold.strip():
        credit_hold = "N"
    if len(credit_hold) != 1:
        raise ValueError("CRED_HOLD must fit in the 1-character field")

    create_date = _text(row.get("CREATE_DT", ""))
    if not create_date.strip():
        create_date = "00000000"
    if len(create_date) != 8:
        raise ValueError("CREATE_DT must fit in the 8-character field")

    record = (
        account_id
        + account_name
        + region_code
        + annual_revenue
        + credit_hold
        + create_date
    )
    if len(record) != 77:
        raise AssertionError("EXPORT_ACCT record must be exactly 77 characters")
    return record
